"""Run a module harness image on QEMU and assert its result.

Modelled on the Cortex-R52 FVP runner.  Every image reports through Arm
semihosting and ends the simulation itself with SYS_EXIT, so the runner only
launches QEMU, captures what the image printed, and judges it.  Both the
result line and QEMU's exit status must say the image passed.

A missing result line is a failure, never a pass: a hang, or a crash before
the first check, must not be able to look like success.
"""

import argparse
import subprocess
import sys

PASS_MARK = "ALL CHECKS PASSED"
FAIL_MARK = "RESULT: FAILED"
FAULT_MARK = "[FAULT]"


def as_text(stream):
    """Normalise a captured stream to str; a timeout hands back bytes."""
    if stream is None:
        return ""
    if isinstance(stream, bytes):
        return stream.decode(errors="replace")
    return stream


def run(qemu, machine, elf, timeout):
    command = [
        qemu,
        "-M", machine,
        "-nographic",
        "-monitor", "none",
        "-serial", "none",
        "-semihosting-config", "enable=on,target=native",
        "-kernel", elf,
    ]

    print("Running:", " ".join(command), flush=True)

    try:
        completed = subprocess.run(
            command, capture_output=True, text=True, timeout=timeout
        )
    except subprocess.TimeoutExpired as expired:
        print(as_text(expired.stdout) + as_text(expired.stderr))
        print(
            f"FAIL: QEMU did not terminate within {timeout}s. Every image is "
            "expected to exit through semihosting SYS_EXIT, so this is a hang.",
            file=sys.stderr,
        )
        return 1

    output = as_text(completed.stdout) + as_text(completed.stderr)
    print(output)

    if FAULT_MARK in output:
        print("FAIL: the image reported an unexpected exception.", file=sys.stderr)
        return 1
    if FAIL_MARK in output:
        print("FAIL: the image reported failing checks.", file=sys.stderr)
        return 1
    if PASS_MARK not in output:
        print("FAIL: the image printed no result line.", file=sys.stderr)
        return 1
    if completed.returncode != 0:
        print(
            f"FAIL: the image reported success but QEMU exited with "
            f"{completed.returncode}.",
            file=sys.stderr,
        )
        return 1

    return 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--qemu", required=True, help="qemu-system-arm executable")
    parser.add_argument("--machine", required=True, help="QEMU machine, e.g. mps2-an385")
    parser.add_argument("--elf", required=True, help="image to run")
    parser.add_argument("--timeout", type=int, default=60, help="seconds before a hang is declared")
    args = parser.parse_args()
    return run(args.qemu, args.machine, args.elf, args.timeout)


if __name__ == "__main__":
    sys.exit(main())
